import{_ as t,o,c as r,a2 as d}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"OpenCode Zen","description":"OpenCode Zen 精選模型網關：官網入口、免費模型列表、付費說明，以及在 MiniTavern 中的填法。","frontmatter":{"title":"OpenCode Zen","description":"OpenCode Zen 精選模型網關：官網入口、免費模型列表、付費說明，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"OpenCode Zen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenCode Zen 精選模型網關：官網入口、免費模型列表、付費說明，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/opencode-zen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/opencode-zen"}]]},"headers":[],"relativePath":"zh-TW/free-cloud/opencode-zen.md","filePath":"zh-TW/free-cloud/opencode-zen.md","lastUpdated":1787224147000}'),a={name:"zh-TW/free-cloud/opencode-zen.md"};function n(i,e,l,c,h,s){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h1><p><a href="https://opencode.ai/" target="_blank" rel="noreferrer">OpenCode</a> 團隊提供的 <strong>AI 網關</strong>：精選、測過的編碼向模型，按請求計費；同時提供若干 <strong>Free（限時/上限內免費）</strong> 文本模型。可與 OpenCode 以外的客戶端共用（含 MiniTavern）。官方說明見 <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Zen 文檔（簡體）</a>。</p><blockquote><p>Zen <strong>不是</strong>純永久免費平臺：多數旗艦模型按量付費，常需綁定賬單 / 充值；下方「免費模型」適合在額度內試用。政策以官網為準。</p></blockquote><h2 id="官網與入口" tabindex="-1">官網與入口 <a class="header-anchor" href="#官網與入口" aria-label="Permalink to &quot;官網與入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資源</th><th>地址</th></tr></thead><tbody><tr><td>Zen 介紹</td><td><a href="https://opencode.ai/en/zen" target="_blank" rel="noreferrer">opencode.ai/zen</a></td></tr><tr><td>登錄 / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>文檔（簡體）</td><td><a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">opencode.ai/docs/zh-cn/zen</a></td></tr><tr><td>模型元數據</td><td><code>https://opencode.ai/zen/v1/models</code></td></tr><tr><td>API Base URL（OpenAI 兼容）</td><td><code>https://opencode.ai/zen/v1</code></td></tr></tbody></table><h2 id="免費怎麼獲取" tabindex="-1">免費怎麼獲取 <a class="header-anchor" href="#免費怎麼獲取" aria-label="Permalink to &quot;免費怎麼獲取&quot;">​</a></h2><ol><li>打開 <a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a>（GitHub / Google）登錄。</li><li>按控制台指引創建 <strong>API Key</strong>。官方流程常要求補充賬單信息；若只想用免費檔，仍建議先看清自動充值是否關閉，避免誤扣費。</li><li>在 MiniTavern 選 <strong>自定義 (OpenAI)</strong>，Base URL 填 <code>https://opencode.ai/zen/v1</code>，模型填下方 <strong>Free</strong> ID。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>免費方式</td><td>若干模型定價為 <strong>Free</strong>（在 OpenCode 上限內）；用於收集反饋，可能隨時調整或下線</td></tr><tr><td>付費方式</td><td>按量付費；餘額低於 $5 時默認可自動充值 $20（可在控制台改或關）</td></tr><tr><td>綁卡</td><td>官方「工作原理」寫明需添加賬單信息；以控制台實際為準</td></tr><tr><td>隱私注意</td><td>免費檔（如 Big Pickle、MiMo Free、Hy3、Nemotron Free、Muse Contributor Free）可能用日誌改進模型；Nemotron 為 NVIDIA 試用端點，勿傳機密</td></tr></tbody></table><p>完整價目與棄用表見 <a href="https://opencode.ai/docs/zh-cn/zen/#%E5%AE%9A%E5%83%B9" target="_blank" rel="noreferrer">Zen · 定價</a>。</p><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>模型 ID <strong>大小寫敏感</strong>。Zen 對不同廠商走不同路徑：<code>/chat/completions</code>、<code>/responses</code>、<code>/messages</code> 或 Gemini 專用路徑。MiniTavern <strong>自定義 (OpenAI)</strong> 走 Chat Completions，請優先選下表 <strong>OpenAI 兼容</strong> 行。</p><p>完整表見 <a href="https://opencode.ai/docs/zh-cn/zen/#%E7%AB%AF%E9%BB%9E" target="_blank" rel="noreferrer">Zen · 端點</a>；也可用 <code>GET https://opencode.ai/zen/v1/models</code>。</p><h3 id="文本-·-免費檔-推薦先試" tabindex="-1">文本 · 免費檔（推薦先試） <a class="header-anchor" href="#文本-·-免費檔-推薦先試" aria-label="Permalink to &quot;文本 · 免費檔（推薦先試）&quot;">​</a></h3><p>均走 <code>…/v1/chat/completions</code>（除 Muse Contributor Free 走 Responses）。</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>mimo-v2.5-free</code></td><td>小米 MiMo V2.5 免費檔</td></tr><tr><td><code>hy3-free</code></td><td>Hy3 Free</td></tr><tr><td><code>big-pickle</code></td><td>隱身模型，免費檔</td></tr><tr><td><code>nemotron-3-ultra-free</code></td><td>NVIDIA Nemotron 試用，勿傳機密</td></tr><tr><td><code>nemotron-3.5-lightning-free</code></td><td>同上</td></tr><tr><td><code>muse-spark-1.2-contributor-free</code></td><td>貢獻者免費檔；走 <code>/responses</code>，<strong>MiniTavern 測連可能不適用</strong>，且允許用提示詞訓練 Meta 模型</td></tr></tbody></table><h3 id="文本-·-付費但-openai-兼容-可選" tabindex="-1">文本 · 付費但 OpenAI 兼容（可選） <a class="header-anchor" href="#文本-·-付費但-openai-兼容-可選" aria-label="Permalink to &quot;文本 · 付費但 OpenAI 兼容（可選）&quot;">​</a></h3><p>適合已充值、仍想用同一 Base URL：</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code> / <code>deepseek-v4-pro</code></td><td>DeepSeek（有 Peak / Off-Peak 價差）</td></tr><tr><td><code>glm-5.1</code> / <code>glm-5.2</code> / <code>glm-5</code></td><td>智譜 GLM</td></tr><tr><td><code>kimi-k2.5</code> / <code>kimi-k2.6</code> / <code>kimi-k2.7-code</code> / <code>kimi-k3</code></td><td>Kimi</td></tr><tr><td><code>minimax-m2.5</code> / <code>minimax-m2.7</code> / <code>minimax-m3</code></td><td>MiniMax</td></tr></tbody></table><h3 id="其它協議-minitavern-慎用" tabindex="-1">其它協議（MiniTavern 慎用） <a class="header-anchor" href="#其它協議-minitavern-慎用" aria-label="Permalink to &quot;其它協議（MiniTavern 慎用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>類型</th><th>示例 ID</th><th>端點類型</th></tr></thead><tbody><tr><td>GPT 系列</td><td><code>gpt-5.5</code>、<code>gpt-5.4-nano</code> 等</td><td><code>/zen/v1/responses</code></td></tr><tr><td>Claude 系列</td><td><code>claude-sonnet-4-6</code>、<code>claude-haiku-4-5</code> 等</td><td><code>/zen/v1/messages</code></td></tr><tr><td>Gemini 系列</td><td><code>gemini-3-flash</code> 等</td><td><code>/zen/v1/models/&lt;id&gt;</code></td></tr></tbody></table><p>上述與 MiniTavern 默認的 OpenAI Chat Completions <strong>不完全同一路徑</strong>；角色扮演聊天請優先用免費檔或上表 OpenAI 兼容模型。需要 Claude 時可改用 App 內 <strong>Claude(Anthropic)</strong> 官方 Key，或換 <a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a> 等統一 OpenAI 網關。</p><h3 id="圖片-視頻" tabindex="-1">圖片 / 視頻 <a class="header-anchor" href="#圖片-視頻" aria-label="Permalink to &quot;圖片 / 視頻&quot;">​</a></h3><p>Zen 文檔當前目錄以<strong>語言模型</strong>為主，<strong>無獨立免費生圖 / 視頻檔</strong>。生圖請看 <a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a> 或 <a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費生圖</a>。</p><h2 id="在-minitavern-裡怎麼填" tabindex="-1">在 MiniTavern 裡怎麼填 <a class="header-anchor" href="#在-minitavern-裡怎麼填" aria-label="Permalink to &quot;在 MiniTavern 裡怎麼填&quot;">​</a></h2><p>通用步驟見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a>。</p><p>路徑：<strong>設置 → 模型 → 模型連接 → 新建</strong></p><ol><li>平臺選 <strong>自定義 (OpenAI)</strong></li><li>Base URL：<code>https://opencode.ai/zen/v1</code></li><li>粘貼 API Key</li><li>模型 ID 填 <code>mimo-v2.5-free</code>（或其它 Free / chat 兼容 ID）</li><li><strong>測試</strong> → 成功後再設為默認</li></ol><blockquote><p>若測連失敗：確認未選 GPT Responses / Claude Messages 專用 ID；關閉自動充值後再試免費檔；對照 <a href="/ultra_guides/zh-TW/manual/errors">錯誤排錯</a>。</p></blockquote><h2 id="相關章節" tabindex="-1">相關章節 <a class="header-anchor" href="#相關章節" aria-label="Permalink to &quot;相關章節&quot;">​</a></h2><ul><li><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端總覽</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a> — 一把 Key 試多款 <code>*-free</code> 閉源/開源模型 + 生圖</li><li><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a></li></ul>',30)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
